def crea_voci(apps, schema_editor):
    Elemento = apps.get_model('turni', 'ElementoPulizia')
    Regola = apps.get_model('turni', 'RegolaPulizia')
    for nome, tipo, luogo, modo, convalida, tasto, minuti, ordine, regole in VOCI:
        e, _ = Elemento.objects.update_or_create(nome=nome, defaults={
            'tipo': tipo, 'luogo': luogo, 'modo': modo, 'convalida': convalida, 'tasto': tasto,
            'minuti_prima_fine': minuti, 'ordine': ordine, 'attivo': True})
        for postazione, fascia in regole:
            Regola.objects.get_or_create(elemento=e, postazione=postazione, fascia=fascia, solo_capoturno=False)
    apps.get_model('turni', 'Dipendente').objects.filter(nome__iexact='LOMBARDO GABRIELE').update(resp_piazzale=True)


